<div class="admin-title"><div><span class="eyebrow">MEMBER DETAILS</span><h1><?= e($person['display_name']) ?></h1><p>@<?= e($person['username']) ?> / #<?= (int)$person['id'] ?></p></div><a class="btn secondary" href="<?= e(au('users')) ?>"><?= t('Back to members') ?></a></div><div class="two-column"><section class="panel"><?= form_start('admin_user') . hidden('id',$person['id']) ?><?php field('display_name','Display name',$person['display_name'],'text',['required'=>'required']);field('email','Email',$person['email'],'email',['required'=>'required']);select_field('role','Account role',options(['user','editor','moderator','admin']),$person['role']);select_field('status','Account status',options(['active','suspended']),$person['status']);check_field('replace_membership','Replace all membership grants with the tier and expiry below',false);select_field('vip_tier','Membership tier',[1=>'VIP 1',2=>'VIP 2',3=>'VIP 3'],max(1,$a->membership->tier($person)));field('vip_until','VIP expiry',$person['vip_until']?date('Y-m-d\TH:i',(int)$person['vip_until']):'','datetime-local');check_field('verified','Manually verified by the site operator',(bool)$person['verified']);field('new_password','Reset password (blank keeps current)','','password',['autocomplete'=>'new-password','minlength'=>'12','maxlength'=>'72']);check_field('creator_enabled','Approved revenue-sharing author',!empty($person['creator_enabled']));field('creator_bps','Author share override (-1 uses default)',(int)$person['creator_bps'],'number',['min'=>'-1','max'=>'10000']);button('Save member'); ?><p class="hint"><?= t('Role, status, email and password changes invalidate existing sessions. Keep at least one active administrator.') ?></p></form></section><section class="panel"><h2><?= t('Ledger-based asset adjustment') ?></h2><div class="mini-list"><?php foreach (\Chengyu\Services\Wallet::CURRENCIES as $currency): ?><div class="row between"><span><?= t($currency) ?></span><strong><?= e(price((int)$person[$currency],$currency)) ?></strong></div><?php endforeach ?></div><?= form_start('admin_wallet') . hidden('user_id',$person['id']) . intent() ?><?php select_field('currency','Asset',options(\Chengyu\Services\Wallet::CURRENCIES));field('delta','Signed adjustment (+ or -; CNY for monetary assets)','','text',['required'=>'required']);field('reason','Audit reason','','text',['required'=>'required','maxlength'=>'180']);field('current_password','Your administrator password','','password',['required'=>'required','autocomplete'=>'current-password']);button('Record adjustment','full','shield'); ?><p class="hint"><?= t('This creates a ledger entry. It does not simulate a successful external payment, and negative balances are refused.') ?></p></form></section></div>
